import{_ as p,a0 as o,w as d,s as r,I as n,x as i,a1 as t,A as e,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Linux/Unix 系統中驗證端口是否被佔用 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux/Unix 系統中驗證端口是否被佔用 | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux/Unix 系統中驗證端口是否被佔用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux/Unix 系統中驗證端口是否被佔用 | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20161110 How to check if port is in use on Linux or Unix","title":"如何在 Linux/Unix 系統中驗證端口是否被佔用","tag":"201612","desc":""},"relativePath":"201612/20161110 How to check if port is in use on Linux or Unix.md","filePath":"[post].md"}'),h={name:"201612/20161110 How to check if port is in use on Linux or Unix.md"};function u(g,s,c,k,f,b){const a=o("Link");return d(),r("div",null,[s[16]||(s[16]=n("h1",{id:"如何在-linux-unix-系統中驗證端口是否被佔用",tabindex:"-1"},[i("如何在 Linux/Unix 系統中驗證端口是否被佔用 "),n("a",{class:"header-anchor",href:"#如何在-linux-unix-系統中驗證端口是否被佔用","aria-label":"Permalink to “如何在 Linux/Unix 系統中驗證端口是否被佔用”"},"​")],-1)),n("p",null,[t(a,{href:"https://www.cyberciti.biz/faq/category/linux/"},{default:e(()=>[...s[0]||(s[0]=[n("img",{src:"https://s0.cyberciti.org/images/category/old/linux-logo.png",alt:""},null,-1)])]),_:1})]),s[17]||(s[17]=l(`<p>在 Linux 或者類 Unix 中，我該如何檢查某個端口是否被佔用？我又該如何驗證 Linux 服務器中有哪些端口處於監聽狀態？</p><p>驗證哪些端口在服務器的網絡接口上處於監聽狀態是非常重要的。你需要注意那些開放端口來檢測網絡入侵。除了網絡入侵，為了排除故障，確認服務器上的某個端口是否被其他應用程序佔用也是必要的。比方説，你可能會在同一個系統中安裝了 Apache 和 Nginx 服務器，所以瞭解是 Apache 還是 Nginx 佔用了 # 80/443 TCP 端口真的很重要。這篇快速教程會介紹使用 <code>netstat</code> 、 <code>nmap</code> 和 <code>lsof</code> 命令來檢查端口使用信息並找出哪些程序正在使用這些端口。</p><h3 id="如何檢查-linux-中的程序和監聽的端口" tabindex="-1">如何檢查 Linux 中的程序和監聽的端口 <a class="header-anchor" href="#如何檢查-linux-中的程序和監聽的端口" aria-label="Permalink to “如何檢查 Linux 中的程序和監聽的端口”">​</a></h3><p>1、 打開一個終端，如 shell 命令窗口。 2、 運行以下任意一行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo lsof -i -P -n | grep LISTEN</span></span>
<span class="line"><span>sudo netstat -tulpn | grep LISTEN</span></span>
<span class="line"><span>sudo nmap -sTU -O IP地址</span></span></code></pre></div><p>下面我們看看這些命令和它們的詳細輸出內容：</p><h3 id="方式-1-lsof-命令" tabindex="-1">方式 1：lsof 命令 <a class="header-anchor" href="#方式-1-lsof-命令" aria-label="Permalink to “方式 1：lsof 命令”">​</a></h3><p>語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lsof -i -P -n</span></span>
<span class="line"><span>$ sudo lsof -i -P -n | grep LISTEN</span></span>
<span class="line"><span>$ doas lsof -i -P -n | grep LISTEN  ### OpenBSD</span></span></code></pre></div><p>輸出如下：</p>`,10)),n("p",null,[t(a,{href:"http://www.cyberciti.biz/faq/unix-linux-check-if-port-is-in-use-command/lsof-outputs/"},{default:e(()=>[...s[1]||(s[1]=[n("img",{src:"https://s0.cyberciti.org/uploads/faq/2016/11/lsof-outputs.png",alt:"Fig.01: Check the listening ports and applications with lsof command"},null,-1)])]),_:1})]),s[18]||(s[18]=l(`<p><em>圖 1：使用 lsof 命令檢查監聽端口和程序</em></p><p>仔細看上面輸出的最後一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sshd    85379     root    3u  IPv4 0xffff80000039e000      0t0  TCP 10.86.128.138:22 (LISTEN)</span></span></code></pre></div><ul><li><code>sshd</code> 是程序的名稱</li><li><code>10.86.128.138</code> 是 <code>sshd</code> 程序綁定 (LISTEN) 的 IP 地址</li><li><code>22</code> 是被使用 (LISTEN) 的 TCP 端口</li><li><code>85379</code> 是 <code>sshd</code> 任務的進程 ID (PID)</li></ul><h3 id="方式-2-netstat-命令" tabindex="-1">方式 2：netstat 命令 <a class="header-anchor" href="#方式-2-netstat-命令" aria-label="Permalink to “方式 2：netstat 命令”">​</a></h3><p>你可以如下面所示使用 <code>netstat</code> 來檢查監聽的端口和程序。</p><p><strong>Linux 中 netstat 語法</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ netstat -tulpn | grep LISTEN</span></span></code></pre></div><p><strong>FreeBSD/MacOS X 中 netstat 語法</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ netstat -anp tcp | grep LISTEN</span></span>
<span class="line"><span>$ netstat -anp udp | grep LISTEN</span></span></code></pre></div><p><strong>OpenBSD 中 netstat 語法</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ netstat -na -f inet | grep LISTEN</span></span>
<span class="line"><span>$ netstat -nat | grep LISTEN</span></span></code></pre></div><h3 id="方式-3-nmap-命令" tabindex="-1">方式 3：nmap 命令 <a class="header-anchor" href="#方式-3-nmap-命令" aria-label="Permalink to “方式 3：nmap 命令”">​</a></h3><p>語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmap -sT -O localhost</span></span>
<span class="line"><span>$ sudo nmap -sU -O 192.168.2.13 ### 列出打開的 UDP 端口</span></span>
<span class="line"><span>$ sudo nmap -sT -O 192.168.2.13 ### 列出打開的 TCP 端口</span></span></code></pre></div><p>示例輸出如下：</p>`,16)),n("p",null,[t(a,{href:"http://www.cyberciti.biz/faq/unix-linux-check-if-port-is-in-use-command/nmap-outputs/"},{default:e(()=>[...s[2]||(s[2]=[n("img",{src:"https://s0.cyberciti.org/uploads/faq/2016/11/nmap-outputs.png",alt:"Fig.02: Determines which ports are listening for TCP connections using nmap"},null,-1)])]),_:1})]),s[19]||(s[19]=l(`<p><em>圖 2：使用 nmap 探測哪些端口監聽 TCP 連接</em></p><p>你可以用一句命令合併 TCP/UDP 掃描：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmap -sTU -O 192.168.2.13</span></span></code></pre></div><h3 id="贈品-對於-windows-用户" tabindex="-1">贈品：對於 Windows 用户 <a class="header-anchor" href="#贈品-對於-windows-用户" aria-label="Permalink to “贈品：對於 Windows 用户”">​</a></h3><p>在 windows 系統下可以使用下面的命令檢查端口使用情況：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>netstat -bano | more</span></span>
<span class="line"><span>netstat -bano | grep LISTENING</span></span>
<span class="line"><span>netstat -bano | findstr /R /C:&quot;[LISTING]&quot;</span></span></code></pre></div><hr>`,7)),n("p",null,[s[4]||(s[4]=i("via: ",-1)),t(a,{href:"https://www.cyberciti.biz/faq/unix-linux-check-if-port-is-in-use-command/"},{default:e(()=>[...s[3]||(s[3]=[i("https://www.cyberciti.biz/faq/unix-linux-check-if-port-is-in-use-command/",-1)])]),_:1})]),n("p",null,[s[8]||(s[8]=i("作者：",-1)),t(a,{href:"https://www.cyberciti.biz/faq/unix-linux-check-if-port-is-in-use-command/"},{default:e(()=>[...s[5]||(s[5]=[i("VIVEK GITE",-1)])]),_:1}),s[9]||(s[9]=i(" 譯者：",-1)),t(a,{href:"https://github.com/GHLandy"},{default:e(()=>[...s[6]||(s[6]=[i("GHLandy",-1)])]),_:1}),s[10]||(s[10]=i(" 校對：",-1)),t(a,{href:"https://github.com/oska874"},{default:e(()=>[...s[7]||(s[7]=[i("oska874",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=i("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[11]||(s[11]=[i("LCTT",-1)])]),_:1}),s[14]||(s[14]=i(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...s[12]||(s[12]=[i("Linux中國",-1)])]),_:1}),s[15]||(s[15]=i(" 榮譽推出",-1))])])}const C=p(h,[["render",u]]);export{T as __pageData,C as default};
